<script setup lang="ts">
import {onMounted,ref} from 'vue';
import {api,download,display,type Actor,type Row} from './api';
import DataTable from './DataTable.vue';
const props=defineProps<{me?:Actor;self?:boolean}>(),emit=defineEmits<{correct:[draft:Row]}>();
const month=ref(new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit'}).format(new Date())),department=ref(''),departments=ref<Row[]>([]),rows=ref<Row[]>([]),daily=ref<Row[]|null>(null),error=ref(''),busy=ref(false);
const states:Row={NORMAL:'正常',LATE:'迟到',EARLY:'早退',LATE_EARLY:'迟到及早退',MISSING:'缺卡',LEAVE:'请假',FIELD:'外勤',REST:'休息日',EXCLUDED:'未纳入统计',FUTURE:'未来日期',IN_PROGRESS:'进行中',RECORDED:'无打卡记录（规则关闭）',PUNCHED:'已打卡（规则关闭）'};
const cols=(pairs:string[])=>pairs.map(p=>{const [key,label]=p.split(':');return {key:key!,label:label!}});
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'加载失败'}finally{busy.value=false}}
async function details(id:number){const from=month.value+'-01';const [y,m]=month.value.split('-').map(Number);const end=new Date(y!,m!,0).getDate();daily.value=await api('/attendance/daily?'+new URLSearchParams({userId:String(id),from,to:month.value+'-'+end}))}
function exportMonthly(){return download('/admin/exports/attendance-monthly.csv?'+new URLSearchParams({month:month.value,...(department.value?{departmentId:department.value}:{})}),'月度考勤.csv')}
async function load(){daily.value=null;rows.value=await api('/attendance/summary?'+new URLSearchParams({month:month.value,...(department.value?{departmentId:department.value}:{}),...(props.self&&props.me?{userId:String(props.me.id)}:{})}));if(props.self&&props.me)await details(props.me.id)}
onMounted(()=>run(async()=>{if(props.me?.roles.split(',').some(r=>['ADMIN','FINANCE'].includes(r)))departments.value=await api('/directory/departments');await load()}));
</script>
<template><section class="card"><h2>{{self?'我的本月考勤':'月度考勤'}}</h2><p v-if="error" class="error" role="alert">{{error}}</p><form class="filters" @submit.prevent="run(load)"><label>考勤月份<input v-model="month" type="month" required /></label><label v-if="!self&&departments.length">考勤部门<select v-model="department"><option value="">全部部门</option><option v-for="d in departments" :key="d.id" :value="String(d.id)">{{d.name}}</option></select></label><button :disabled="busy">查询月度考勤</button></form><p v-if="busy" role="status">正在加载考勤…</p><p class="muted">北京时间。规则生效前、入职前、未来日期和当前停用账号不判缺卡；今天尚未到下班时间显示进行中。</p>
<button v-if="me?.roles.split(',').includes('ADMIN')" :disabled="busy" @click="run(exportMonthly)">导出月度考勤</button>
<div v-if="self" class="stats"><p v-for="r in rows" :key="r.user_id">应出勤 {{r.expectedDays}} · 正常 {{r.normalDays}} · 迟到 {{r.lateCount}} 次 / {{r.lateMinutes}} 分 · 早退 {{r.earlyCount}} 次 / {{r.earlyMinutes}} 分 · 缺卡 {{r.missingCount}} · 请假 {{r.leaveDays}} 天 · 外勤 {{r.fieldDays}} 天</p></div>
<DataTable v-if="!self" :rows="rows" :columns="cols(['employee_no:工号','user_name:姓名','department_name:部门','expectedDays:应出勤','normalDays:正常','lateCount:迟到次数','lateMinutes:迟到分钟','earlyCount:早退次数','earlyMinutes:早退分钟','missingCount:缺卡次数','leaveDays:请假天数','fieldDays:外勤天数','restDays:休息日'])"><template #actions="{row}"><button :disabled="busy" @click="run(()=>details(row.user_id))">每日明细</button></template></DataTable>
<template v-if="daily"><h3>每日考勤明细</h3><p v-for="d in daily" :key="d.day" :class="{error:['LATE','EARLY','LATE_EARLY','MISSING'].includes(d.status)}">{{d.day}} · {{states[d.status]}} · 首卡 {{display(d.firstPunch)}} · 末卡 {{display(d.lastPunch)}} · 迟到 {{d.lateMinutes}} 分 · 早退 {{d.earlyMinutes}} 分 {{d.missingPunch}} <span v-if="d.requestIds.length">关联单号：{{d.requestIds.join('、')}}</span> <button v-if="self&&['LATE','EARLY','LATE_EARLY','MISSING'].includes(d.status)" @click="emit('correct',{kind:'CORRECTION',correctionAt:d.day+(d.missingPunch==='上班卡'?'T09:00':'T18:00'),punchKind:d.field?'FIELD':'NORMAL'})">发起补卡</button></p></template></section></template>
